function openMemories(){const items=[...state.items].filter(i=>i.notes||i.dateAcquired).sort((a,b)=>(b.dateAcquired||b.createdAt||'').localeCompare(a.dateAcquired||a.createdAt||''));openModal(`${modalHead('📖 Mochi Memories')}<p class="tiny muted">A little history of the things you chose to keep.</p>${items.length?`<div class="memory-timeline" style="margin-top:15px">${items.map(i=>`<div class="memory-entry"><div class="memory-dot">${coverOf(i)?`<img src="${coverOf(i)}" alt="">`:(collectionFor(i.collectionId)?.emoji||'🍡')}</div><button class="memory-card" data-memory-item="${i.id}" style="text-align:left"><div class="memory-date">${i.dateAcquired?fmtDate(i.dateAcquired):'Added to Mochi'}</div><b>${esc(i.name)}</b><div class="tiny muted">${esc(collectionFor(i.collectionId)?.name||'')}</div>${i.notes?`<p>${esc(i.notes)}</p>`:''}</button></div>`).join('')}</div>`:`<div class="empty"><div class="empty-art">📖</div><h3>No memories yet</h3><p>Add a date or a little story to an item and it will appear here.</p></div>`}`);$$('[data-memory-item]').forEach(b=>b.onclick=()=>openItemDetail(b.dataset.memoryItem))}
