function openWrapped(){const year=String(new Date().getFullYear()),month=monthKey(),yearItems=state.items.filter(i=>(i.dateAcquired||i.createdAt||'').startsWith(year)),monthItems=state.items.filter(i=>(i.dateAcquired||i.createdAt||'').startsWith(month)),topSeries=topCount('series',yearItems)[0],topCharacter=topCount('character',yearItems)[0],yearSpent=yearItems.reduce((a,i)=>a+Number(i.pricePaid||0)*qty(i),0);openModal(`${modalHead('🎀 Mochi Wrapped')}<div class="wrapped-card"><div class="tiny muted">${year} so far</div><div class="wrapped-number">${yearItems.reduce((a,i)=>a+qty(i),0)} treasures</div><div class="tiny">Your collection grew a little more like you this year ♡</div><div class="wrapped-grid"><div class="wrapped-mini"><b>${money(yearSpent)}</b><span>spent this year</span></div><div class="wrapped-mini"><b>${monthItems.reduce((a,i)=>a+qty(i),0)}</b><span>added this month</span></div><div class="wrapped-mini"><b>${esc(topSeries?.[0]||'—')}</b><span>top series</span></div><div class="wrapped-mini"><b>${esc(topCharacter?.[0]||'—')}</b><span>top character</span></div></div></div>${yearItems.length?`<section class="panel" style="margin-top:12px"><h3>Your ${year} highlights</h3><div class="h-scroll">${[...yearItems].sort((a,b)=>(b.dateAcquired||'').localeCompare(a.dateAcquired||'')).slice(0,8).map(renderMiniItem).join('')}</div></section>`:''}`);$$('[data-item-id]').forEach(b=>b.onclick=()=>openItemDetail(b.dataset.itemId))}
